    "html": "<style>
  :root {
    --color-neon-glow: #34d59a;
    --color-neon-muted: #285d49;
    --color-whiteout: #ffffff;
    --color-blackout: #000000;
    --color-graphite-deep: #151617;
    --color-graphite: #242628;
    --color-graphite-light: #303236;
    --color-ash: #797d86;
    --color-cloud: #c9cbcf;
    --font-inter: 'Inter', sans-serif;
    --font-geistmono: 'Fira Code', 'Source Code Pro', monospace;
  }

  .terminal-wrapper {
    background: var(--color-blackout);
    padding: 40px 32px;
    max-width: 600px;
    box-sizing: border-box;
    font-family: var(--font-inter);
  }

  .terminal-label {
    font-family: var(--font-inter);
    font-size: 12px;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--color-ash);
    margin-bottom: 16px;
    font-weight: 400;
  }

  .terminal-block {
    background: var(--color-graphite-deep);
    border-radius: 4px;
    border: 1px solid var(--color-graphite-light);
    overflow: hidden;
  }

  .terminal-titlebar {
    background: var(--color-graphite);
    padding: 10px 16px;
    display: flex;
    align-items: center;
    gap: 7px;
    border-bottom: 1px solid var(--color-graphite-light);
  }

  .terminal-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--color-graphite-light);
  }

  .terminal-body {
    padding: 20px 20px 24px;
    font-family: var(--font-geistmono);
    font-size: 13px;
    line-height: 1.65;
    letter-spacing: -0.3px;
  }

  .terminal-prompt {
    color: var(--color-cloud);
    margin-bottom: 16px;
    display: block;
  }

  .terminal-prompt .dollar {
    color: var(--color-neon-glow);
    margin-right: 8px;
  }

  .terminal-output-title {
    color: var(--color-cloud);
    margin-bottom: 10px;
    display: block;
  }

  .terminal-step {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    color: var(--color-ash);
    margin-bottom: 6px;
  }

  .terminal-step-indicator {
    width: 10px;
    height: 10px;
    border-radius: 2px;
    background: var(--color-graphite-light);
    flex-shrink: 0;
    margin-top: 3px;
  }

  .terminal-step-indicator.active {
    background: var(--color-neon-glow);
  }

  .terminal-step.completed {
    color: var(--color-ash);
  }

  .terminal-step.in-progress {
    color: var(--color-cloud);
  }

  .step-text strong {
    font-weight: 600;
    color: var(--color-cloud);
  }

  .step-text.neon strong {
    color: var(--color-neon-glow);
  }

  .terminal-divider {
    height: 1px;
    background: var(--color-graphite-light);
    margin: 14px 0;
  }

  .terminal-stat {
    display: flex;
    align-items: center;
    gap: 0;
    font-family: var(--font-geistmono);
    font-size: 13px;
    letter-spacing: -0.3px;
    color: var(--color-ash);
  }

  .terminal-stat .stat-label {
    color: var(--color-ash);
  }

  .terminal-stat .stat-value {
    color: var(--color-neon-glow);
    margin-left: 8px;
  }

  .terminal-stat .stat-separator {
    color: var(--color-graphite-light);
    margin: 0 12px;
  }
</style>

